try {
    const operationOptions = $ctrl.enService.modals.advancedFilterModal.dropdowns.FILTER_OPERATION.values || [];
    $ctrl.operationMap = new Map(
        operationOptions.map(op => [op.value, op.label])
    );

    $ctrl.propertyMap = new Map();
    if ($ctrl.filterProperties) {
        Object.entries($ctrl.filterProperties).forEach(([label, value]) => {
            $ctrl.propertyMap.set(value, label);
        });
    }

    $ctrl.onQuickSearchConfigUpdate();

    const validFilters = $ctrl.utilityService.getValidFilters($ctrl.filtersApplied);
    const validSorts = $ctrl.utilityService.getValidSorts($ctrl.sortsApplied);

    $ctrl.updateAdvancedFiltersCountAndButtonLabel(validFilters?.length, validSorts?.length);
    $ctrl.processAppliedAdvancedFiltersChipListValues();
    $ctrl.processAppliedSortsChipListValues();
} catch (e) {
    console.error("Error initializing advanced filter component", e);
}

try {
    let queryString;

    if ($ctrl.isUsingQuickSearch && $ctrl.quickSearchFieldValue) {
        $ctrl.isAdvancedFiltersModalOpen = true;
        $ctrl.filtersApplied = [{
            property: $ctrl.quickSearchCustomColumnValue,
            operation: $ctrl.quickSearchCustomOperation,
            value: $ctrl.quickSearchFieldValue
        }];
    }
    const originalFiltersApplied = structuredClone($ctrl.filtersApplied);
    const originalSortsApplied = structuredClone($ctrl.sortsApplied);

    const modalResponse = await $ctrl.$modal.open("advanced-filter-modal", {
        filterProperties: $ctrl.filterProperties,
        filterValueChoices: $ctrl.filterValueChoices,
        filtersApplied: $ctrl.filtersApplied,
        sortsApplied: $ctrl.sortsApplied,
        currentPage: $ctrl.currentPageKey
    });

    if (modalResponse.result !== "cancel" && modalResponse.result !== null) {
        $ctrl.filtersApplied = modalResponse.filtersApplied;
        $ctrl.filtersAppliedCount = modalResponse.filtersAppliedCount;

        let filterPart = null;

        if ($ctrl.filtersAppliedCount > 0) {
            $ctrl.quickSearchFieldValue = "";
            $ctrl.isUsingAdvancedFilters = true;
            $ctrl.filterQueryString = modalResponse.filterQueryString;
            filterPart = modalResponse.filterQueryString;
        } else {
            $ctrl.isUsingAdvancedFilters = false;
            $ctrl.filterQueryString = null;
            $ctrl.filtersApplied = [
                {
                    property: null,
                    operation: null,
                    value: ""
                }
            ];
            filterPart = null;
        }

        if (modalResponse.sortsApplied) {
            $ctrl.sortsApplied = modalResponse.sortsApplied;
        }

        $ctrl.sortsAppliedCount = modalResponse.sortsAppliedCount;
        let sortPart = null;

        if ($ctrl.sortsAppliedCount > 0) {
            $ctrl.isUsingSorts = true;
            $ctrl.sortQueryString = modalResponse.sortQueryString;
            sortPart = modalResponse.sortQueryString;
        } else {
            $ctrl.isUsingSorts = false;
            $ctrl.sortQueryString = null;
            $ctrl.sortsApplied = [
                {
                    value: null,
                    order: "ASC"
                }
            ];
            sortPart = null;
        }

        const queryParts = [];

        if (filterPart) queryParts.push(filterPart);

        if (sortPart) {
            queryParts.push(`sort=${sortPart}`);
        }

        queryString = queryParts.length > 0 ? queryParts.join('&') : null;

        $ctrl.updateAdvancedFiltersCountAndButtonLabel($ctrl.filtersAppliedCount, $ctrl.sortsAppliedCount);
        $ctrl.processAppliedAdvancedFiltersChipListValues();
        $ctrl.processAppliedSortsChipListValues();

        $ctrl.onFilterChange({
            queryString: queryString
        });
    } else {
        $ctrl.filtersApplied = originalFiltersApplied;
        $ctrl.sortsApplied = originalSortsApplied;
    }

    $ctrl.isAdvancedFiltersModalOpen = false;
} catch (e) {
    console.error("Error encountered in advanced filter creation", e);
}

try {
    const operations = $ctrl.enService.modals.advancedFilterModal.dropdowns.FILTER_OPERATION.values.filter((operation) => operation.value !== "isnull" && operation.value !== "isnotnull");
    const configModal = await $ctrl.$modal.open("configure-table-and-quick-search-modal", {
        properties: $ctrl.filterProperties,
        operations: operations,
        defaultConfig: $ctrl.defaultConfig,
        currentPageKey: $ctrl.currentPageKey,
        columns: $ctrl.columns,
    });

    if (configModal.result === "saved") {
        $ctrl.onQuickSearchConfigUpdate();
        $ctrl.onColumnConfigChange({
            columns: configModal.columns.filter((c) => c.checked)
    });
    }

} catch (e) {
    console.error("Error encountered in table and quick search configuration", e);
}

try {
    $ctrl.filtersApplied = [
        {
            property: null,
            operation: null,
            value: ""
        }
    ];

    $ctrl.sortsApplied = [
        {
            property: null,
            order: "ASC"
        }
    ];
    $ctrl.sortsAppliedCount = 0;

    $ctrl.updateAdvancedFiltersCountAndButtonLabel(0);
    $ctrl.processAppliedAdvancedFiltersChipListValues();
    $ctrl.quickSearchFieldValue = "";
    $ctrl.filterQueryString = null;
    $ctrl.sortQueryString = null;
    $ctrl.isUsingAdvancedFilters = false;
    $ctrl.isUsingSorts = false;

    $ctrl.onFilterChange({
        queryString: null
    });
} catch (e) {
    console.error("Error clearing filters", e);
}

try {
    let queryString = null;

    if (newValue?.trim()) {
        const filter = {
            property: $ctrl.quickSearchCustomColumnValue,
            operation: $ctrl.quickSearchCustomOperation,
            value: newValue
        };

        queryString = $ctrl.utilityService.buildFilterQuery(filter);
        // $ctrl.filtersApplied = [filter];
        $ctrl.updateAdvancedFiltersCountAndButtonLabel(1);
        $ctrl.isUsingQuickSearch = true;
    } else {
        // $ctrl.filtersApplied = [{
        //     property: null,
        //     operation: null,
        //     value: ""
        // }];
        $ctrl.updateAdvancedFiltersCountAndButtonLabel(0);
    }

    $ctrl.onFilterChange({
        queryString: queryString
    });
} catch (e) {
    console.error("Error executing quick search", e);
}

try {
    let appliedFiltersCount;
    if (!newValues?.length) {
        $ctrl.filtersApplied = [
            {
                property: null,
                operation: null,
                value: ""
            }
        ];
        appliedFiltersCount = 0;
        $ctrl.isUsingAdvancedFilters = false;
        $ctrl.filterQueryString = null;
    } else {
        $ctrl.filtersApplied = $ctrl.filtersApplied.filter((filterObj) => {
            const displayString = $ctrl.generateReadableFilterLabel(filterObj);
            return newValues.includes(displayString);
        });

        appliedFiltersCount = $ctrl.filtersApplied?.length;

        $ctrl.filterQueryString = $ctrl.filtersApplied
            .map(f => $ctrl.utilityService.buildFilterQuery(f))
            .filter(str => str && str !== '')
            .join('&');
    }

    $ctrl.updateAdvancedFiltersCountAndButtonLabel(appliedFiltersCount);

    const queryParts = [];
    if ($ctrl.filterQueryString) {
        queryParts.push($ctrl.filterQueryString);
    }

    if ($ctrl.sortQueryString) {
        queryParts.push($ctrl.sortQueryString.startsWith('sort=') 
            ? $ctrl.sortQueryString 
            : `sort=${$ctrl.sortQueryString}`);
    }

    const finalQueryString = queryParts.length > 0 ? queryParts.join('&') : null;
    $ctrl.onFilterChange({
        queryString: finalQueryString
    });

} catch (e) {
    console.error("Error applying advanced filter chip list value changes", e);
}

try {
    let appliedSortsCount;
    if (!newValues?.length) {
        $ctrl.sortsApplied = [
            {
                value: null,
                order: "ASC"
            }
        ];
        $ctrl.sortQueryString = null;
        appliedSortsCount = 0;
        $ctrl.isUsingSorts = false;
    } else {
        $ctrl.sortsApplied = $ctrl.sortsApplied.filter((sortObj) => {
            const displayString = $ctrl.generateReadableSortLabel(sortObj);
            return newValues.includes(displayString);
        });

        appliedSortsCount = $ctrl.sortsApplied.length;
        $ctrl.isUsingSorts = true;

        const validSorts = $ctrl.sortsApplied.filter(s => s.value);

        if (validSorts.length > 0) {
            $ctrl.sortQueryString = validSorts
                .map(s => {
                    const order = s.order || 'ASC';
                    return `${s.value}:${order}`;
                })
                .join(',');
        } else {
            $ctrl.sortQueryString = null;
        }
    }

    $ctrl.sortsAppliedCount = appliedSortsCount;
    $ctrl.updateAdvancedFiltersCountAndButtonLabel($ctrl.filtersAppliedCount, appliedSortsCount);

    const queryParts = [];

    if ($ctrl.filterQueryString) {
        queryParts.push($ctrl.filterQueryString);
    }

    if ($ctrl.sortQueryString) {
        queryParts.push($ctrl.sortQueryString.startsWith('sort=') 
            ? $ctrl.sortQueryString 
            : `sort=${$ctrl.sortQueryString}`);
    }

    const finalQueryString = queryParts.length > 0 ? queryParts.join('&') : null;

    $ctrl.onFilterChange({
        queryString: finalQueryString
    });

} catch (e) {
    console.error("Error applying sort chip list value changes", e);
}

try {
    if ($ctrl.filtersApplied && $ctrl.filtersApplied.length) {

        $ctrl.appliedAdvancedFiltersChipListValues = $ctrl.filtersApplied
            .map(filter => $ctrl.generateReadableFilterLabel(filter))
            .filter(label => label && label !== "");

        if ($ctrl.appliedAdvancedFiltersChipListValues?.length) {
            $ctrl.isUsingAdvancedFilters = true;
        }

    } else {
        $ctrl.appliedAdvancedFiltersChipListValues = [];
    }
} catch (e) {
    console.error("Error processing applied advanced filter chip list values", e);
    $ctrl.appliedAdvancedFiltersChipListValues = [];
}

try {
    if ($ctrl.sortsApplied && $ctrl.sortsApplied.length) {

        $ctrl.appliedSortsChipListValues = $ctrl.sortsApplied
            .filter(sort => sort && sort.value)
            .map(sort => $ctrl.generateReadableSortLabel(sort))
            .filter(label => label && label !== "");

        if ($ctrl.appliedSortsChipListValues?.length) {
            $ctrl.isUsingSorts = true;
        }

    } else {
        $ctrl.appliedSortsChipListValues = [];
    }
} catch (e) {
    console.error("Error processing applied sort chip list values", e);
    $ctrl.appliedSortsChipListValues = [];
}

try {
    $ctrl.filtersAppliedCount = overrideFiltersAppliedCount ?? $ctrl.filtersAppliedCount ?? $ctrl.filtersApplied?.length ?? 0;
    $ctrl.sortsAppliedCount = overrideSortsAppliedCount ?? $ctrl.sortsAppliedCount ?? $ctrl.sortsApplied?.length ?? 0;
    $ctrl.advancedFiltersButtonLabel = `Filters (${$ctrl.filtersAppliedCount}) | Sorts (${$ctrl.sortsAppliedCount})`;
} catch (e) {
    console.error("Error updating advanced filter count and button labels" , e);
}

const { property, operation, value } = filter;
if (!property || !operation) return '';

const readableProp = $ctrl.propertyMap?.get(property) || property;
const readableOp = $ctrl.operationMap?.get(operation) || operation.toUpperCase();

let displayValue = value;

if (property === 'pipelineId' || property === 'pipelineStageId') {
    const choices = $ctrl.filterValueChoices && $ctrl.filterValueChoices[property];
    if (Array.isArray(choices)) {
        const match = choices.find(c => String(c.value) === String(value));
        if (match) {
            displayValue = match.label;
        }
    }
}

if (value !== undefined && value !== null) {
    return `${readableProp} ${readableOp} "${displayValue}"`;
}

return `${readableProp} ${readableOp}`;

const { value, order } = sort;
if (!value) return '';

const readableProp = $ctrl.propertyMap?.get(value) || value;
const readableOrder = (order && order.toUpperCase() === 'DESC') ? 'DESCENDING' : 'ASCENDING';

return `${readableProp} ${readableOrder}`;

