if ($ctrl.isAdvancedFiltersModalOpen) return;

const noValueOperations = ['isnull', 'isnotnull'];
const populatedFilters = $ctrl.utilityService.getValidFilters($ctrl.filtersApplied ?? []);

const filtersCount = populatedFilters.length;

if (filtersCount > 0) {
    $ctrl.updateAdvancedFiltersCountAndButtonLabel(filtersCount);
    $ctrl.processAppliedAdvancedFiltersChipListValues();
    $ctrl.isUsingAdvancedFilters = true;
}
